import numpy as np
from scipy.optimize import least_squares
def m1(p,t,A):
    return p[0]-p[1]*t**p[2]*A**p[3]
def m2(p,t,A):
    return p[0]*np.exp(-p[1]*t)+p[2]-p[3]*t**p[4]*A**p[5]
def m3(p,t,A):
    return p[0]+p[1]*t+p[2]*A*np.exp(-p[3]*t)+p[4]*A**p[5]*t**p[6]
for name,f,npar in [('m1',m1,4),('m2',m2,6),('m3',m3,7)]:
    bestr=None
    rng=np.random.default_rng(0)
    for k in range(40):
        p0=rng.uniform(-2,2,npar)
        if name=='m1': p0[2]=abs(p0[2])*2; p0[3]=abs(p0[3])*2
        try:
            r=least_squares(lambda p: f(p,t,A)-dA_dt,p0,max_nfev=2000)
            if bestr is None or r.cost<bestr.cost: bestr=r
        except Exception: pass
    print(name, np.mean(bestr.fun**2)/np.var(dA_dt), np.round(bestr.x,4))

import numpy as np
from scipy.optimize import least_squares
def m4(p,t,A):
    return p[0]*t**p[1]*np.exp(-p[2]*t) - p[3]*t**p[4]*A**p[5]
def m5(p,t,A):
    return p[0]*t**p[1]*np.exp(-p[2]*t) - p[3]*t**p[4]*A**p[5] + p[6]
rng=np.random.default_rng(1)
for name,f,npar in [('m4',m4,6),('m5',m5,7)]:
    bestr=None
    for k in range(200):
        p0=rng.uniform(0,2,npar)
        try:
            r=least_squares(lambda p: f(p,t,A)-dA_dt,p0,max_nfev=3000)
            if np.all(np.isfinite(r.fun)) and (bestr is None or r.cost<bestr.cost): bestr=r
        except Exception: pass
    print(name, np.mean(bestr.fun**2)/np.var(dA_dt), np.round(bestr.x,4))

